(477400, 44985, 4767, '<td valign="top">interesting composition.</td>', 'interesting composition.', '2003-11-08 13:20:19.000000', NULL, 1),
(477403, 45430, 4767, '<td valign="top">GOOD lighting!  The blue background makes trhe babies breath, not those lovely roses, dominant on my monitor, but... nice shot!</td>', 'GOOD lighting!  The blue background makes trhe babies breath, not those lovely roses, dominant on my monitor, but... nice shot!', '2003-11-08 13:21:51.000000', NULL, 1),
(477405, 44927, 4767, '<td valign="top">Gorgeous flowers, impeccable lighting...  those delicate petals? may have a little too much competition from the basket withes at this size and resolution.  Excellent photo!</td>', 'Gorgeous flowers, impeccable lighting...  those delicate petals? may have a little too much competition from the basket withes at this size and resolution.  Excellent photo!', '2003-11-08 13:30:14.000000', NULL, 1),
(477406, 45046, 4767, '<td valign="top">Oh, this is NICE!  Subtle, powerful, GREAT!   9</td>', 'Oh, this is NICE!  Subtle, powerful, GREAT!   9', '2003-11-08 13:31:17.000000', NULL, 1),
(477408, 45260, 4767, '<td valign="top">A teeeny bit hot on the citrus skins.  The yellow is overpowered by the blue, and could almost be oranges on my monitor.  Probably my Sony mis-showing, I hope.</td>', 'A teeeny bit hot on the citrus skins.  The yellow is overpowered by the blue, and could almost be oranges on my monitor.  Probably my Sony mis-showing, I hope.', '2003-11-08 13:34:36.000000', NULL, 1),
