INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(477995, 44726, 8953, '<td valign="top">Very Nice composition. just a little bit of rotation clock wise to level the hutch 8</td>', 'Very Nice composition. just a little bit of rotation clock wise to level the hutch 8', '2003-11-09 14:39:45.000000', NULL, 1),
(477998, 45603, 8953, '<td valign="top">Well done! the colors and lighting are gorgeous. 10!</td>', 'Well done! the colors and lighting are gorgeous. 10!', '2003-11-09 14:42:16.000000', NULL, 1),
(478000, 45354, 8953, '<td valign="top">Another wow Image. the muted tones are perpect! nice job.10</td>', 'Another wow Image. the muted tones are perpect! nice job.10', '2003-11-09 14:45:52.000000', NULL, 1),
(478017, 44519, 13557, '<td valign="top">I like the idea, but I think your angle is a touch off to get the right effect ( the strawberry has a split look).  I also think you could have used a glass with a thinner stem and it would have helped make the split sharper.</td>', 'I like the idea, but I think your angle is a touch off to get the right effect ( the strawberry has a split look).  I also think you could have used a glass with a thinner stem and it would have helped make the split sharper.', '2003-11-09 16:36:37.000000', NULL, 1),
(478018, 45233, 13557, '<td valign="top">sharp but busy</td>', 'sharp but busy', '2003-11-09 16:37:36.000000', NULL, 1),
(478021, 45211, 3295, '<td valign="top">It is fantastic... Sorry I didn''t notice its beauty the first time through... <br/><br/><i>Message edited by author 2003-11-12 22:59:44.</i></td>', 'It is fantastic... Sorry I didn''t notice its beauty the first time through... ', '2003-11-09 16:41:42.000000', '2003-11-12 22:59:44.000000', 1),
(478023, 45287, 13557, '<td valign="top">I like the color, but the background is a bit busy</td>', 'I like the color, but the background is a bit busy', '2003-11-09 16:43:37.000000', NULL, 1),
(478036, 44713, 14007, '<td valign="top">you made me get my teddies out the box!  always good to see a photo that provokes emotion...</td>', 'you made me get my teddies out the box!  always good to see a photo that provokes emotion...', '2003-11-09 17:10:04.000000', NULL, 1),
(478048, 45542, 12674, '<td valign="top">Very nice composition and excellent color, but not quite a still life in my mind.</td>', 'Very nice composition and excellent color, but not quite a still life in my mind.', '2003-11-09 17:36:12.000000', NULL, 1),
(478049, 44711, 12674, '<td valign="top">Nice composition and contrasting background; might''ve benefited from slight rotation and cropping to set bottle in more vertical position - it leans a bit.</td>', 'Nice composition and contrasting background; might''ve benefited from slight rotation and cropping to set bottle in more vertical position - it leans a bit.', '2003-11-09 17:38:55.000000', NULL, 1),
(478052, 44853, 10970, '<td valign="top">Nice but I''m not sure how it qualifies as a still life.</td>', 'Nice but I''m not sure how it qualifies as a still life.', '2003-11-09 17:46:45.000000', NULL, 1),
(478056, 45477, 10970, '<td valign="top">I think the lamp is so bright and colorful it calls attention away from the the food and drinks which should be the focus of the picture.  I like the idea but the lamp is destracting.  The food seem a little blured.</td>', 'I think the lamp is so bright and colorful it calls attention away from the the food and drinks which should be the focus of the picture.  I like the idea but the lamp is destracting.  The food seem a little blured.', '2003-11-09 17:53:40.000000', NULL, 1),
(478057, 44830, 10970, '<td valign="top">So Simple and so nice.</td>', 'So Simple and so nice.', '2003-11-09 17:54:05.000000', NULL, 1),
(478078, 45376, 2158, '<td valign="top">Perhaps a bit overcrowded, but I like the idea.</td>', 'Perhaps a bit overcrowded, but I like the idea.', '2003-11-09 18:08:08.000000', NULL, 1),
(478092, 45442, 2158, '<td valign="top">I find the lighting a little too harsh, with too many overexposed patches on the left of the fruit.</td>', 'I find the lighting a little too harsh, with too many overexposed patches on the left of the fruit.', '2003-11-09 18:29:59.000000', NULL, 1),
(478099, 45262, 10806, '<td valign="top">little grainy but good</td>', 'little grainy but good', '2003-11-09 18:37:57.000000', NULL, 1),
(478106, 45539, 10806, '<td valign="top">ther is a reflection on the backdrop, but other wise good job</td>', 'ther is a reflection on the backdrop, but other wise good job', '2003-11-09 19:01:22.000000', NULL, 1),
(478107, 45387, 10806, '<td valign="top">less light would be more suitable</td>', 'less light would be more suitable', '2003-11-09 19:01:55.000000', NULL, 1),
(478109, 44673, 10806, '<td valign="top">would be better if no pieces in the forground.would make it more visible as to what you are trying to capture in this pic</td>', 'would be better if no pieces in the forground.would make it more visible as to what you are trying to capture in this pic', '2003-11-09 19:03:06.000000', NULL, 1),
(478110, 45046, 10806, '<td valign="top">ii like this alot top 10 for sure good luck!! 10</td>', 'ii like this alot top 10 for sure good luck!! 10', '2003-11-09 19:04:06.000000', NULL, 1),
(478113, 45468, 10806, '<td valign="top">awsome pic great negtives and positives</td>', 'awsome pic great negtives and positives', '2003-11-09 19:05:45.000000', NULL, 1),
(478119, 44853, 10510, '<td valign="top">This is not still life to me, but a capture of a special moment in time.  It is a beautiful photo and it shows such a loving relationship.  I''m giving it a 10 even though I don''t think it really relates to the challenge title.</td>', 'This is not still life to me, but a capture of a special moment in time.  It is a beautiful photo and it shows such a loving relationship.  I''m giving it a 10 even though I don''t think it really relates to the challenge title.', '2003-11-09 19:15:09.000000', NULL, 1),
(478134, 45563, 2866, '<td valign="top">Congratulations!  This is the worst photo I''ve ever seen on this site.</td>', 'Congratulations!  This is the worst photo I''ve ever seen on this site.', '2003-11-09 19:39:58.000000', NULL, 1),
(478136, 44870, 10402, '<td valign="top">The cat''s face is centered, defying the "rule of thirds", and the leaves that frame the cat have such bright colors that they tend to draw the eye away from the cat. Yet the composition does work. The cat is so obviously the center of interest that the viewer fights the distractions to focus on it. It conveys to me something about the natural stealthiness of felines. Unfortunately it isn''t a "still life" composed from inanimate objects (although you certainly aren''t the only one that misinterpreted the challenge and photographed a "still" living subject).</td>', 'The cat''s face is centered, defying the "rule of thirds", and the leaves that frame the cat have such bright colors that they tend to draw the eye away from the cat. Yet the composition does work. The cat is so obviously the center of interest that the viewer fights the distractions to focus on it. It conveys to me something about the natural stealthiness of felines. Unfortunately it isn''t a "still life" composed from inanimate objects (although you certainly aren''t the only one that misinterpreted the challenge and photographed a "still" living subject).', '2003-11-09 19:50:54.000000', NULL, 1),
(478140, 44711, 10402, '<td valign="top">Nice arrangement with a classic draped background. Good lighting. Seems tilted to the right.</td>', 'Nice arrangement with a classic draped background. Good lighting. Seems tilted to the right.', '2003-11-09 19:57:28.000000', NULL, 1),
(478143, 45564, 10402, '<td valign="top">Exudes elegance. The blue netting adds a touch of coolness.</td>', 'Exudes elegance. The blue netting adds a touch of coolness.', '2003-11-09 19:59:35.000000', NULL, 1),
(478147, 45348, 10145, '<td valign="top">The little drip of water is a nice touch</td>', 'The little drip of water is a nice touch', '2003-11-09 20:07:55.000000', NULL, 1),
(478148, 45426, 10145, '<td valign="top">Such a cute little girl!  Nice photo, good luck!</td>', 'Such a cute little girl!  Nice photo, good luck!', '2003-11-09 20:10:32.000000', NULL, 1),
(478149, 45287, 10145, '<td valign="top">Nice, crisp photo!</td>', 'Nice, crisp photo!', '2003-11-09 20:12:13.000000', NULL, 1),
(478151, 44856, 10145, '<td valign="top">A little less light and more sharpness/focus on the kitty would improve the photo</td>', 'A little less light and more sharpness/focus on the kitty would improve the photo', '2003-11-09 20:17:26.000000', NULL, 1),
(478153, 45635, 10402, '<td valign="top">Great lighting and background. The composition shows off the subject fairly well. But I personally don''t find it very interesting.</td>', 'Great lighting and background. The composition shows off the subject fairly well. But I personally don''t find it very interesting.', '2003-11-09 20:19:27.000000', NULL, 1),
(478156, 45323, 10402, '<td valign="top">I think black and white is a good choice here; color would have been striking, but then the nice assortment of textures here wouldn''t be so apparent. A simple border would have been more effective.</td>', 'I think black and white is a good choice here; color would have been striking, but then the nice assortment of textures here wouldn''t be so apparent. A simple border would have been more effective.', '2003-11-09 20:28:44.000000', NULL, 1),
(478160, 45537, 10402, '<td valign="top">The primary colors make this very striking and the cropping gives it an abstract feeling. I like the way the vases are arranged.  The white negative space has an interesting shape.</td>', 'The primary colors make this very striking and the cropping gives it an abstract feeling. I like the way the vases are arranged.  The white negative space has an interesting shape.', '2003-11-09 20:33:20.000000', NULL, 1),
(478166, 45420, 1280, '<td valign="top">Lovely, classic, simplicity. And yes, the lighting is well done. Congrats and good luck!</td>', 'Lovely, classic, simplicity. And yes, the lighting is well done. Congrats and good luck!', '2003-11-09 20:43:18.000000', NULL, 1),
(478168, 45247, 10402, '<td valign="top">Leafy sea dragons are amazing creatures. Great composition. I don''t mind the tail being blurred, but the focus on the head and body is too soft; some sharpening would help. Although this is a great photo,  it is a "still" life, not a "still life" (you''re not the only one that misinterpreted the challenge like this).</td>', 'Leafy sea dragons are amazing creatures. Great composition. I don''t mind the tail being blurred, but the focus on the head and body is too soft; some sharpening would help. Although this is a great photo,  it is a "still" life, not a "still life" (you''re not the only one that misinterpreted the challenge like this).', '2003-11-09 20:44:08.000000', NULL, 1),
(478170, 45347, 10402, '<td valign="top">Creative and very well done, although I don''t particularly care for it.</td>', 'Creative and very well done, although I don''t particularly care for it.', '2003-11-09 20:46:46.000000', NULL, 1),
(478172, 45627, 1280, '<td valign="top">One of my faves. Beautifully composed and wonderful colour and exposure, as well as dof. Overall very appealing.</td>', 'One of my faves. Beautifully composed and wonderful colour and exposure, as well as dof. Overall very appealing.', '2003-11-09 20:49:38.000000', NULL, 1),
(478176, 45375, 4767, '<td valign="top">Why does this make me hungry?  Looks delicious, however the bowl od pecans appeard larger than the pie, and I think it''s the pie you''re stressing.  Peehaps if the pie were closer and the bowl behind it, perhaps cropped a little might be more powerful.  (Did I say the pie makes me hungry?  Nice pic!)</td>', 'Why does this make me hungry?  Looks delicious, however the bowl od pecans appeard larger than the pie, and I think it''s the pie you''re stressing.  Peehaps if the pie were closer and the bowl behind it, perhaps cropped a little might be more powerful.  (Did I say the pie makes me hungry?  Nice pic!)', '2003-11-09 20:54:27.000000', NULL, 1),
(478178, 45504, 4767, '<td valign="top">wonderful eye!   A unique vision!</td>', 'wonderful eye!   A unique vision!', '2003-11-09 20:55:37.000000', NULL, 1),
(478179, 45288, 10402, '<td valign="top">Dramatic angle and lighting. A little sharpening would make the focus match the starkness of the image.</td>', 'Dramatic angle and lighting. A little sharpening would make the focus match the starkness of the image.', '2003-11-09 20:55:43.000000', NULL, 1),
(478184, 45605, 14012, '<td valign="top">I like this. I think it may have looked a little better if the lighting was a tad softer and focused more on the top of the apple to reduce the finger reflections on the bottom.</td>', 'I like this. I think it may have looked a little better if the lighting was a tad softer and focused more on the top of the apple to reduce the finger reflections on the bottom.', '2003-11-09 20:59:57.000000', NULL, 1),
(478186, 45083, 14012, '<td valign="top">Very Nice</td>', 'Very Nice', '2003-11-09 21:03:02.000000', NULL, 1),
(478188, 45355, 4767, '<td valign="top">ah, je me souviens...</td>', 'ah, je me souviens...', '2003-11-09 21:03:42.000000', NULL, 1),
(478190, 45021, 10402, '<td valign="top">Nice arrangement. The doll at the very edge is a nice touch, adding some "life" as well as a splash of contrasting color. The saturated noisy color is a bit crazy, but I rather like it. It goes well with the subject.</td>', 'Nice arrangement. The doll at the very edge is a nice touch, adding some "life" as well as a splash of contrasting color. The saturated noisy color is a bit crazy, but I rather like it. It goes well with the subject.', '2003-11-09 21:04:06.000000', NULL, 1),
(478191, 45243, 14012, '<td valign="top">Lighting is a little harsh for me. Nice though.</td>', 'Lighting is a little harsh for me. Nice though.', '2003-11-09 21:05:02.000000', NULL, 1),
(478196, 45630, 14012, '<td valign="top">Just a little too soft for me</td>', 'Just a little too soft for me', '2003-11-09 21:13:01.000000', NULL, 1),
(478197, 45260, 10402, '<td valign="top">The miniature pitcher in front of the large bowl of lemons give this image a subtly surrealistic feeling. The lemonade is unnaturally yellow, which adds to the effect.</td>', 'The miniature pitcher in front of the large bowl of lemons give this image a subtly surrealistic feeling. The lemonade is unnaturally yellow, which adds to the effect.', '2003-11-09 21:13:30.000000', NULL, 1),
(478199, 45450, 14012, '<td valign="top">Nice shot, would have been even better if that darn line wasn''t going thorugh there.</td>', 'Nice shot, would have been even better if that darn line wasn''t going thorugh there.', '2003-11-09 21:14:32.000000', NULL, 1),
(478200, 45479, 14001, '<td valign="top">Terrific lighting!</td>', 'Terrific lighting!', '2003-11-09 21:14:41.000000', NULL, 1),
(478201, 45597, 14012, '<td valign="top">I really like this.</td>', 'I really like this.', '2003-11-09 21:18:47.000000', NULL, 1),
