INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(481201, 45590, 9643, '<td valign="top">I know that comments should be constructive but I think sometimes it is appropriate to just be appreciative.  This is IMO the most beautiful photo in this collection.  You have captured the best in color, tone and lighting for both classical still life and modern digital photography.  I am very far from expert in photography but I''m quite schooled in the arts and one doesn''t often have the opportunity  to speak directly to the "artist" to express the inner joy his/her work has brought.  10</td>', 'I know that comments should be constructive but I think sometimes it is appropriate to just be appreciative.  This is IMO the most beautiful photo in this collection.  You have captured the best in color, tone and lighting for both classical still life and modern digital photography.  I am very far from expert in photography but I''m quite schooled in the arts and one doesn''t often have the opportunity  to speak directly to the "artist" to express the inner joy his/her work has brought.  10', '2003-11-11 23:13:42.000000', NULL, 1),
(481202, 45558, 5705, '<td valign="top">this gets a "High" mark from me-- LOL</td>', 'this gets a "High" mark from me-- LOL', '2003-11-11 23:14:11.000000', NULL, 1),
